use vstd::prelude::*;

verus! {
    /// splitlines: for each input string, wrap it in a Vec<String> of length 1.
    ///
    /// Guarantees:
    /// 1) The outer Vec has the same length as the input Vec.
    /// 2) Each inner Vec has exactly one element, equal to the corresponding input.
    fn splitlines(a: Vec<String>, _keepends: bool) -> Vec<Vec<String>>
        // No preconditions.
        ensures
            // Same number of outer elements.
            result.len() == a.len(),
        ensures
            // Each inner Vec has length exactly 1.
            forall |i: usize| i < a.len() ==> result[i].len() == 1,
        ensures
            // The sole element matches the original string.
            forall |i: usize| i < a.len() ==> result[i][0] == a[i],
    {
        a.into_iter().map(|s| vec![s]).collect()
    }
}

